<?php
if(!isset($db)){http_response_code(404);exit;}
function launchSetup(){global $db;
$db->exec("CREATE TABLE IF NOT EXISTS onb_trip_updates(id INT AUTO_INCREMENT PRIMARY KEY,trip_id INT NOT NULL,title VARCHAR(150) NOT NULL,body TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
$db->exec("CREATE TABLE IF NOT EXISTS onb_packing(user_id INT NOT NULL,item VARCHAR(100) NOT NULL,done TINYINT NOT NULL DEFAULT 0,PRIMARY KEY(user_id,item)) ENGINE=InnoDB");
$db->exec("CREATE TABLE IF NOT EXISTS onb_newsletter(user_id INT PRIMARY KEY,subscribed TINYINT NOT NULL DEFAULT 0,changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB");
$db->exec("CREATE TABLE IF NOT EXISTS onb_email_queue(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,subject VARCHAR(150) NOT NULL,body TEXT NOT NULL,kind VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY unique_message(user_id,kind,subject)) ENGINE=InnoDB");
$db->exec("CREATE TABLE IF NOT EXISTS onb_reset_tokens(user_id INT PRIMARY KEY,digest CHAR(64) NOT NULL,expires_at DATETIME NOT NULL) ENGINE=InnoDB");
}
function launchItems(){return ['Passport validity checked','Visa requirements checked','Travel insurance reviewed','Flight details checked','Accommodation details checked','Emergency contacts saved','Packing completed'];}
function launchAction($action,$u,$admin){global $db,$c;launchSetup();
if($action==='launch_reset_request'){
$ip=$_SERVER['REMOTE_ADDR']??'unknown';if(q('SELECT COUNT(*) FROM attempts WHERE ip=? AND created_at > NOW()-INTERVAL 15 MINUTE',[$ip])->fetchColumn()>=5)throw new RuntimeException('Try again later.');q('INSERT INTO attempts(ip) VALUES(?)',[$ip]);
$a=q("SELECT id,email FROM users WHERE email=? AND role='traveller'",[strtolower(p('email'))])->fetch();
if($a&&!empty($c['public_url'])&&filter_var($c['public_url'],FILTER_VALIDATE_URL)&&str_starts_with($c['public_url'],'https://')){$raw=bin2hex(random_bytes(32));q('INSERT INTO onb_reset_tokens(user_id,digest,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE)) ON DUPLICATE KEY UPDATE digest=VALUES(digest),expires_at=VALUES(expires_at)',[$a['id'],hash('sha256',$raw)]);mail($a['email'],'Our Next Boarding password reset',"Reset within 30 minutes: ".$c['public_url'].'?page=reset&code='.$raw);}
go('page=reset_sent');}
if($action==='launch_reset'){if(strlen(p('password'))<12||strlen(p('password'))>200||!preg_match('/^[a-f0-9]{64}$/D',p('code')))throw new RuntimeException('Invalid reset or password.');$db->beginTransaction();try{$id=q('SELECT user_id FROM onb_reset_tokens WHERE digest=? AND expires_at>NOW() FOR UPDATE',[hash('sha256',p('code'))])->fetchColumn();if(!$id)throw new RuntimeException('Reset link expired.');q("UPDATE users SET password=? WHERE id=? AND role='traveller'",[password_hash(p('password'),PASSWORD_DEFAULT),$id]);q('DELETE FROM onb_reset_tokens WHERE user_id=?',[$id]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}session_destroy();go('page=login');}
if(!$u)throw new RuntimeException('Sign in required.');
if($action==='launch_packing'){foreach(launchItems() as $i=>$item)q('INSERT INTO onb_packing(user_id,item,done) VALUES(?,?,?) ON DUPLICATE KEY UPDATE done=VALUES(done)',[$u['id'],$item,isset($_POST['pack_'.$i])?1:0]);}
elseif($action==='launch_consent'){q('INSERT INTO onb_newsletter(user_id,subscribed) VALUES(?,?) ON DUPLICATE KEY UPDATE subscribed=VALUES(subscribed)',[$u['id'],p('subscribe')==='yes'?1:0]);}
elseif($action==='launch_update'&&$admin){if(!p('title')||strlen(p('title'))>150||!p('body')||strlen(p('body'))>10000||!q('SELECT id FROM trips WHERE id=?',[(int)p('trip_id')])->fetchColumn())throw new RuntimeException('Complete update.');q('INSERT INTO onb_trip_updates(trip_id,title,body) VALUES(?,?,?)',[(int)p('trip_id'),p('title'),p('body')]);}
elseif($action==='launch_campaign'&&$admin){if(!p('title')||strlen(p('title'))>120||preg_match('/[\r\n]/',p('title'))||!p('body')||strlen(p('body'))>10000)throw new RuntimeException('Complete campaign.');q("INSERT IGNORE INTO onb_email_queue(user_id,subject,body,kind) SELECT user_id,?,?,'marketing' FROM onb_newsletter WHERE subscribed=1",[p('title'),p('body')]);}
else throw new RuntimeException('Access denied.');go('page=travelhub');}
function launchView($u,$admin){if(!$u){echo '<p>Sign in to access your travel hub.</p>';return;}launchSetup();bookingSetup();?>
<div class="onb-dash"><div class="dash-hero"><span>OUR NEXT BOARDING</span><h1><?=$admin?'Communications & marketing':'Your travel hub'?></h1><p><?=$admin?'Manage announcements and consent-based campaigns.':'Prepare for your journey and stay informed.'?></p></div>
<?php if($admin):?><h2>Trip announcements</h2><?php form('launch_update');?><label>Journey<select name="trip_id"><?php foreach(q('SELECT id,title FROM trips') as $t):?><option value="<?=$t['id']?>"><?=h($t['title'])?></option><?php endforeach;?></select></label><?php field('title','Announcement title');area('body','Announcement');?><button>Publish</button></form><h2>Marketing campaigns</h2><p><?=h(q('SELECT COUNT(*) FROM onb_newsletter WHERE subscribed=1')->fetchColumn())?> opted-in accounts. Queue only; delivery requires configured mail worker.</p><?php form('launch_campaign');field('title','Email subject');area('body','Email content');?><button>Queue campaign</button></form><div class="metrics"><?php foreach(q('SELECT status,COUNT(*) AS n FROM onb_email_queue GROUP BY status') as $r):?><article><span><?=h($r['status'])?></span><strong><?=h($r['n'])?></strong></article><?php endforeach;?></div>
<?php else:?><h2>Travel preparation</h2><?php $done=q('SELECT item,done FROM onb_packing WHERE user_id=?',[$u['id']])->fetchAll(PDO::FETCH_KEY_PAIR);form('launch_packing');foreach(launchItems() as $i=>$item):?><label><input type="checkbox" name="pack_<?=$i?>" <?=!empty($done[$item])?'checked':''?>> <?=h($item)?></label><?php endforeach;?><button>Save checklist</button></form><h2>Travel preferences</h2><?php form('launch_consent');?><label><input type="checkbox" name="subscribe" value="yes" <?=q('SELECT subscribed FROM onb_newsletter WHERE user_id=?',[$u['id']])->fetchColumn()?'checked':''?>> Receive optional travel offers by email</label><button>Save preferences</button></form><p><a href="?page=bookings">My bookings and statements</a> · <a href="?page=concierge">Boarding Concierge</a></p><?php endif;?>
<h2>Journey announcements</h2><?php foreach(q('SELECT a.*,t.title AS journey FROM onb_trip_updates a JOIN trips t ON t.id=a.trip_id'.($admin?'':" WHERE EXISTS(SELECT 1 FROM onb_bookings b WHERE b.trip_id=a.trip_id AND b.user_id=? AND b.stage IN ('confirmed','completed')) OR EXISTS(SELECT 1 FROM travellers v WHERE v.trip_id=a.trip_id AND v.user_id=?)").' ORDER BY a.id DESC',$admin?[]:[$u['id'],$u['id']]) as $r):?><article><small><?=h($r['journey'].' · '.$r['created_at'])?></small><h3><?=h($r['title'])?></h3><p><?=nl2br(h($r['body']))?></p></article><?php endforeach;?></div><?php }
